import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast'
import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import { aeoPromptsCreateDashboard } from 'products/web_analytics/frontend/generated/api'
import type { AEOVisibilityDashboardApi } from 'products/web_analytics/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface contentAutopilotVisibilityDashboardLogicValues {
    creatingVisibilityDashboard: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface contentAutopilotVisibilityDashboardLogicActions {
    createVisibilityDashboard: () => {
        value: true
    }
    createVisibilityDashboardFinished: () => {
        value: true
    }
}

export type contentAutopilotVisibilityDashboardLogicType = MakeLogicType<
    contentAutopilotVisibilityDashboardLogicValues,
    contentAutopilotVisibilityDashboardLogicActions
>

export const contentAutopilotVisibilityDashboardLogic = kea<contentAutopilotVisibilityDashboardLogicType>([
    path(['products', 'webAnalytics', 'contentAutopilot', 'contentAutopilotVisibilityDashboardLogic']),
    actions({
        createVisibilityDashboard: true,
        createVisibilityDashboardFinished: true,
    }),
    reducers({
        creatingVisibilityDashboard: [
            false,
            {
                createVisibilityDashboard: () => true,
                createVisibilityDashboardFinished: () => false,
            },
        ],
    }),
    listeners(({ actions }) => ({
        createVisibilityDashboard: async (_, breakpoint) => {
            let dashboard: AEOVisibilityDashboardApi
            try {
                dashboard = await aeoPromptsCreateDashboard(String(teamLogic.values.currentTeamIdStrict))
            } catch (error: any) {
                lemonToast.error(`Couldn't create the dashboard${error?.detail ? `: ${error.detail}` : ''}`)
                breakpoint()
                actions.createVisibilityDashboardFinished()
                return
            }
            // pinned: analytics event name, renaming breaks the dashboard funnel
            posthog.capture('web analytics content autopilot visibility dashboard created', {
                dashboard_id: dashboard.id,
            })
            // Stops here when the person left the overview while the request ran, so a late response does not
            // navigate them away from where they are now.
            breakpoint()
            actions.createVisibilityDashboardFinished()
            router.actions.push(urls.dashboard(dashboard.id))
            // New subscriptions default to weekly, so the form opens ready for a weekly delivery.
            lemonToast.success(`Dashboard "${dashboard.name}" created. Subscribe to get it every week.`, {
                button: {
                    label: 'Subscribe weekly',
                    action: () => {
                        // pinned: analytics event name, renaming breaks the dashboard funnel
                        posthog.capture('web analytics content autopilot visibility dashboard subscribe clicked', {
                            dashboard_id: dashboard.id,
                        })
                        router.actions.push(urls.dashboardSubscription(dashboard.id, 'new'))
                    },
                },
            })
        },
    })),
])
